mapper.select:
SELECT , AS distanceMeters, (SELECT MIN(s.price) FROM show_schedule s WHERE s.cinema_id = c.cinema_id AND s.status = 'on_sale' AND s.start_time >= CURRENT_TIMESTAMP AND s.movie_id = #{movieId}) AS minPrice FROM cinema c WHERE <= #{radiusMeters}
AND EXISTS (SELECT 1 FROM show_schedule s WHERE s.cinema_id = c.cinema_id AND s.movie_id = #{movieId} AND s.status = 'on_sale' AND s.start_time >= CURRENT_TIMESTAMP)
ORDER BY
minPrice ASC, distanceMeters ASC distanceMeters ASC, minPrice ASC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE cinema
city_id = #{cityId}, name = #{name}, address = #{address}, lat = #{lat}, lng = #{lng}, traffic_note = #{trafficNote}, tags_json = #{tagsJson}, updated_at = CURRENT_TIMESTAMP
WHERE cinema_id = #{cinemaId}
